/**
 * Feed-card derivatives of the seed JPEGs in public/looks.
 * Detail views keep the original file. Generated by scripts/optimize-feed-images.py.
 */
import { FEED_MANIFEST } from "./feed-manifest.ts";

export type FeedSource = { w: number; url: string };

export type FeedEntry = {
  w: number;
  h: number;
  avif: FeedSource[];
  webp: FeedSource[];
  jpeg: FeedSource[];
};

/** Phone plates are full-bleed. Wide tiles shrink as the grid fills in. */
export const FEED_GRID_SIZES = "(min-width: 1440px) 25vw, (min-width: 1024px) 33vw, (min-width: 768px) 50vw, 100vw";

/** Desktop lead is two of three columns. Tablet lead is the full content width. */
export const FEED_LEAD_SIZES = "(min-width: 1024px) 66vw, 100vw";

export const FEED_PLATE_SIZES = "100vw";

export function feedEntryFor(src: string | null | undefined): FeedEntry | null {
  if (!src || !src.startsWith("/looks/") || src.includes("..")) return null;
  return FEED_MANIFEST[src] ?? null;
}

export function feedSrcSet(sources: FeedSource[]): string {
  return sources.map((source) => `${source.url} ${source.w}w`).join(", ");
}

export function largestSource(sources: FeedSource[]): FeedSource | null {
  let best: FeedSource | null = null;
  for (const source of sources) {
    if (!best || source.w > best.w) best = source;
  }
  return best;
}

/** Intrinsic box for the largest derivative, preserving the original aspect. */
export function feedBox(entry: FeedEntry): { width: number; height: number } {
  const width = largestSource(entry.avif)?.w ?? largestSource(entry.webp)?.w ?? entry.w;
  const height = Math.max(1, Math.round((width * entry.h) / entry.w));
  return { width, height };
}
